<?php
$id=(int)($_GET['id']??0);$record=null;if($id){$q=$pdo->prepare('SELECT i.*,e.name,e.category_id,e.description FROM equipment_items i JOIN equipment e ON e.id=i.equipment_id WHERE i.id=?');$q->execute([$id]);$record=$q->fetch();if(!$record){redirect('?page=equipment');}}
$cats=$pdo->query('SELECT id,name FROM equipment_categories ORDER BY name')->fetchAll();$error='';verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$category=(int)($_POST['category_id']??0);$code=strtoupper(trim($_POST['asset_code']??''));$condition=$_POST['condition_label']??'Good';$status=$_POST['status']??'Available';if($record && $record['status']==='On Loan')$status='On Loan';$valid=in_array($condition,['Good','Fair','Needs inspection','Damaged'],true)&&(in_array($status,['Available','Awaiting Inspection','Under Repair','Retired'],true)||($record && $record['status']==='On Loan' && $status==='On Loan'));if($status==='Available'&&in_array($condition,['Damaged','Needs inspection'],true)){$error='Damaged items, or items that need inspection, cannot be marked Available. Choose Awaiting Inspection or Under Repair.';}elseif($name===''||strlen($name)>120||!$category||!preg_match('/^[A-Z0-9-]{2,30}$/',$code)||!$valid){$error='Enter a name, category, valid asset ID, condition and status.';}else{try{$pdo->beginTransaction();if($id){$q=$pdo->prepare('UPDATE equipment SET name=?,category_id=?,description=? WHERE id=?');$q->execute([$name,$category,trim($_POST['description']??''),$record['equipment_id']]);$q=$pdo->prepare('UPDATE equipment_items SET asset_code=?,condition_label=?,status=?,notes=? WHERE id=?');$q->execute([$code,$condition,$status,trim($_POST['notes']??''),$id]);}else{$q=$pdo->prepare('INSERT INTO equipment(name,category_id,description) VALUES(?,?,?)');$q->execute([$name,$category,trim($_POST['description']??'')]);$eid=(int)$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO equipment_items(equipment_id,asset_code,condition_label,status,notes) VALUES(?,?,?,?,?)');$q->execute([$eid,$code,$condition,$status,trim($_POST['notes']??'')]);$id=(int)$pdo->lastInsertId();}log_activity($pdo,$record?'Updated equipment':'Added equipment','equipment',$id);$pdo->commit();flash('Equipment record saved.');redirect('?page=equipment-view&id='.$id);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='That asset ID may already be in use. Please check and try again.';}}}
layout_start($id?'Edit equipment':'Add equipment','equipment'); ?><div class="page-heading"><div><a class="back-link" href="?page=equipment">← Equipment</a><h1><?=$id?'Edit equipment':'Add equipment'?></h1><p class="muted">Record one physical item with a unique asset ID.</p></div></div><?php if($error): ?><div class="alert error"><?=h($error)?></div><?php endif; ?><section class="panel form-panel"><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Equipment name<input name="name" required maxlength="120" value="<?=h($record['name']??$_POST['name']??'')?>" placeholder="e.g. Folding wheelchair"></label><label>Category<select name="category_id" required><option value="">Choose category</option><?php foreach($cats as $c): ?><option value="<?=$c['id']?>" <?=((int)($record['category_id']??$_POST['category_id']??0)===$c['id'])?'selected':''?>><?=h($c['name'])?></option><?php endforeach; ?></select></label><label>Asset ID<input name="asset_code" required maxlength="30" value="<?=h($record['asset_code']??$_POST['asset_code']??'')?>" placeholder="CS-0001"><small>Letters, numbers and hyphens only.</small></label><label>Condition<select name="condition_label"><?php foreach(['Good','Fair','Needs inspection','Damaged'] as $v): ?><option <?=($record['condition_label']??'Good')===$v?'selected':''?>><?=$v?></option><?php endforeach; ?></select></label><label>Status<select name="status"><?php foreach(($record && $record['status']==='On Loan'?['On Loan']:['Available','Awaiting Inspection','Under Repair','Retired']) as $v): ?><option <?=($record['status']??'Available')===$v?'selected':''?>><?=$v?></option><?php endforeach; ?></select><small>Items currently on loan are updated through the loan workflow.</small></label><label class="span-two">Description<textarea name="description" rows="3"><?=h($record['description']??$_POST['description']??'')?></textarea></label><label class="span-two">Inventory notes<textarea name="notes" rows="3"><?=h($record['notes']??$_POST['notes']??'')?></textarea></label><div class="form-actions span-two"><a class="button ghost" href="?page=equipment">Cancel</a><button class="button primary">Save equipment</button></div></form></section><?php layout_end();
